package top.monitorglobal.tv;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
public final class MainActivity extends Activity {
 private OfficialUpdater updater;private LinearLayout content;private TextView status;private Button start;private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable refresh=new Runnable(){public void run(){update();handler.postDelayed(this,3000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(52,28,52,36);scroll.addView(content);setContentView(scroll);
  label("MONITOR GLOBAL TV",28,true);label("Versão "+BuildConfig.VERSION_NAME+" · M6+ no mundo, sismos no Brasil e tsunami",18,false);status=label("Conferindo configuração…",16,false);
  button("1 · Permitir exibição sobre outros aplicativos",v->{try{startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(ActivityNotFoundException e){try{startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}catch(ActivityNotFoundException ignored){Prefs.status(this,"Abra as permissões nas configurações do aparelho.");}}});
  start=button("2 · Ativar monitoramento",v->{if(Prefs.get(this).getBoolean("enabled",false)){stopService(new Intent(this,MonitorService.class));Prefs.get(this).edit().putBoolean("enabled",false).apply();update();return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},7);}Prefs.get(this).edit().putBoolean("enabled",true).apply();launch(MonitorService.START);update();});
  button("Replay · Buscar último sismo M6+ ou no Brasil (72 h)",v->launch(MonitorService.REPLAY));
  button("Maiores de hoje · parcial até agora",v->launch(MonitorService.SUMMARY_TODAY));
  button("Replay · Resumo de ontem completo (6 s por sismo)",v->launch(MonitorService.SUMMARY_REPLAY));
  button("3 · Testar sismo com indicação de tsunami (fictício)",v->launch(MonitorService.TEST));
  button("4 · Testar revisão M7,2 → M6,9 (fictícia)",v->launch(MonitorService.TEST_REVISION));
  button("5 · Testar aviso de tsunami (fictício)",v->launch(MonitorService.TEST_TSUNAMI));
  button("6 · Testar encerramento de tsunami (fictício)",v->launch(MonitorService.TEST_END));
  button("Testar tsunami sem ameaça (dados fictícios)",v->launch(MonitorService.TEST_NO_THREAT));
  button("7 · Testar sequência completa em 10 segundos (fictícia)",v->launch(MonitorService.TEST_SEQUENCE));
  button("Diagnóstico local · memória e desenho da tarja",v->startActivity(new Intent(this,DiagnosticsActivity.class)));
  updater=new OfficialUpdater(this,s->{Prefs.get(this).edit().putString("updateStatus",s).apply();update();});button("Verificar atualização oficial",v->updater.check());
  Switch targets=new Switch(this);targets.setText("Aviso menor · M5,0–5,9 raso nas áreas monitoradas");targets.setTextColor(Color.WHITE);targets.setTextSize(17);targets.setPadding(12,10,12,10);targets.setChecked(Prefs.get(this).getBoolean("targetAlerts",true));targets.setOnCheckedChangeListener((v,checked)->{Prefs.get(this).edit().putBoolean("targetAlerts",checked).putBoolean("targetsReady",false).putLong("targetSettingsRevision",System.currentTimeMillis()).apply();});content.addView(targets);
  button("Escolher áreas monitoradas para M5+",v->{Set<String> disabled=new HashSet<>(Prefs.get(this).getStringSet("disabledTargetAreas",Collections.emptySet()));boolean[] checked=new boolean[TargetAreaNames.ALL.length];for(int i=0;i<checked.length;i++)checked[i]=!disabled.contains(TargetAreaNames.ALL[i]);new AlertDialog.Builder(this).setTitle("Áreas M5+ · escolha as regiões").setMultiChoiceItems(TargetAreaNames.ALL,checked,(dialog,index,on)->{if(on)disabled.remove(TargetAreaNames.ALL[index]);else disabled.add(TargetAreaNames.ALL[index]);}).setPositiveButton("Salvar",(dialog,which)->Prefs.get(this).edit().putStringSet("disabledTargetAreas",disabled).putBoolean("targetsReady",false).putLong("targetSettingsRevision",System.currentTimeMillis()).apply()).setNegativeButton("Cancelar",null).show();});
  label("Aviso menor por 8 segundos: M5,0–5,9, até 70 km de profundidade, em raios de 160 a 230 km das áreas escolhidas. Não é previsão de danos nem lista mundial completa. Profundidade desconhecida não dispara o aviso menor. M6+, Brasil e tsunami mantêm suas regras.",15,false);
  button("Testar aviso menor M5+ (fictício, em 10 s)",v->launch(MonitorService.TEST+"_TARGET"));
  button("Chuva em São Paulo: "+rainModeLabel(),v->{int next=(Prefs.get(this).getInt("rainMode",2)+1)%3;Prefs.get(this).edit().putInt("rainMode",next).apply();((Button)v).setText("Chuva em São Paulo: "+rainModeLabel());if(Prefs.get(this).getBoolean("enabled",false))launch(MonitorService.START);});
  button("Testar cartão e gotas de chuva (fictício, em 10 s)",v->launch(MonitorService.TEST+"_RAIN"));
  label("Chuva opcional · São Paulo capital: desligado, só cartão ou cartão com gotas. Usa estimativas por minuto do Rainbow Weather para um ponto da capital. Cartão por 12 segundos quando a chuva se aproxima, começa, muda de intensidade ou deixa de ser prevista. mm/h é intensidade estimada; mm nos próximos 60 minutos é acumulado previsto. Início e término só aparecem quando a fonte permite estimar. Sismos e tsunami têm prioridade. Não acompanha sua localização.",15,false);
  Switch sound=new Switch(this);sound.setText("Som dos avisos · usa o volume de notificações do aparelho");sound.setTextColor(Color.WHITE);sound.setTextSize(17);sound.setPadding(12,10,12,10);sound.setChecked(Prefs.get(this).getBoolean("sound",true));sound.setOnCheckedChangeListener((v,checked)->Prefs.get(this).edit().putBoolean("sound",checked).apply());content.addView(sound);
  Switch daily=new Switch(this);daily.setText("Resumo automático à meia-noite · horário de Brasília");daily.setTextColor(Color.WHITE);daily.setTextSize(17);daily.setPadding(12,10,12,10);daily.setChecked(Prefs.get(this).getBoolean("dailyAuto",true));daily.setOnCheckedChangeListener((v,checked)->{Prefs.get(this).edit().putBoolean("dailyAuto",checked).apply();if(Prefs.get(this).getBoolean("enabled",false))launch(MonitorService.START);});content.addView(daily);
  label("À meia-noite: resumo do dia encerrado. Se a TV estiver desligada ou sem internet, tenta recuperar o último dia encerrado ao retomar o monitoramento. Alertas reais têm prioridade; o resumo interrompido volta depois.",15,false);
  button("Duração: "+Prefs.get(this).getInt("seconds",20)+" segundos",v->{int current=Prefs.get(this).getInt("seconds",20),next=current==15?20:current==20?30:current==30?60:current==60?90:current==90?120:15;Prefs.get(this).edit().putInt("seconds",next).apply();((Button)v).setText("Duração: "+next+" segundos");});
  label("Depois de ativar, volte ao conteúdo que deseja assistir. A faixa não captura os botões do controle e fecha automaticamente.",16,false);
  label("Sismo com tsunami: alterna a cada 8 segundos por pelo menos 32 segundos. Replay busca o último sismo M6+ ou no Brasil das últimas 72 horas, inclusive enquanto a TV estava desligada. Sem internet, tenta o último registro local.",15,false);
  label("Replay do resumo de ontem: até cinco maiores sismos do dia anterior completo, de 00h a 23h59 de Brasília. Maiores de hoje mostra apenas o parcial do dia atual e não substitui o replay de ontem. Sem internet, o replay usa o resumo completo de ontem salvo no aparelho; nunca troca por um parcial ou por outro dia. Cada sismo tem seis segundos completos de leitura, mais animações. Alertas reais têm prioridade.",15,false);
  label("Cobertura equivalente às regras sísmicas do Telegram: USGS, EMSC e GEOFON para M6+ globais; USP/RSBR, USGS, EMSC e GEOFON para sismos no Brasil, sem magnitude mínima. Estimativas de agências diferentes são identificadas separadamente de revisões da mesma fonte. Revisões importantes e boletins oficiais de tsunami por região, incluindo SEM AMEAÇA e encerramentos. Falha de uma fonte não interrompe as outras.",15,false);
  label("Primeira conexão: os eventos existentes viram referência, sem disparar avisos antigos. Consultas a cada 30 segundos. O aparelho precisa continuar ligado e com acesso à internet.",15,false);
  label("A exibição sobre outros aplicativos e a permanência em segundo plano ainda precisam ser testadas nesta TV/Fire Stick. O teste demonstrativo não confirma a chegada de um alerta real.",15,false);
  label("Setas: navegar · OK: selecionar · Voltar: sair da configuração",14,false);
 }
 private String rainModeLabel(){int mode=Prefs.get(this).getInt("rainMode",2);return mode==0?"desligado":mode==1?"só cartão":"cartão com gotas";}
 private void launch(String action){try{startForegroundService(new Intent(this,MonitorService.class).setAction(action));}catch(RuntimeException e){Prefs.status(this,"Não foi possível iniciar. Verifique as permissões do aparelho.");}}
 private TextView label(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(bold?Color.WHITE:Color.rgb(186,209,211));t.setPadding(0,8,0,8);if(bold)t.setTypeface(null,Typeface.BOLD);content.addView(t);return t;}
 private Button button(String s,View.OnClickListener listener){Button b=new Button(this);b.setText(s);b.setTextSize(17);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setOnClickListener(listener);b.setPadding(14,9,14,9);b.setOnFocusChangeListener((v,focused)->{GradientDrawable bg=new GradientDrawable();bg.setColor(Color.rgb(22,44,53));bg.setCornerRadius(10);bg.setStroke(focused?3:1,focused?Color.rgb(121,212,199):Color.rgb(53,78,85));b.setBackground(bg);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,6,0,6);content.addView(b,p);return b;}
 private void update(){if(status==null)return;boolean overlay=Settings.canDrawOverlays(this),enabled=Prefs.get(this).getBoolean("enabled",false);long last=Prefs.get(this).getLong("lastCheck",0);String when=last==0?"Ainda sem consulta confirmada":new SimpleDateFormat("HH:mm:ss",Locale.getDefault()).format(new Date(last));status.setText((overlay?"Sobreposição permitida":"Sobreposição não permitida · notificações comuns podem não aparecer na TV")+"\n"+Prefs.get(this).getString("status","Pronto para configurar")+" · "+when+"\n"+Prefs.get(this).getString("sourceHealth","Fontes ainda não verificadas")+" · Última consulta há "+(last==0?"—":Math.max(0,(System.currentTimeMillis()-last)/1000)+" s")+"\n"+Prefs.get(this).getString("updateStatus","Canal oficial do projeto · instalação com sua confirmação")+"\n"+(Prefs.get(this).getInt("rainMode",2)==0?"Chuva em São Paulo: desligado":Prefs.get(this).getString("rainStatus","Chuva em São Paulo: aguardando consulta")));start.setText(enabled?"Parar monitoramento":"2 · Ativar monitoramento");}
 @Override protected void onDestroy(){if(updater!=null)updater.close();super.onDestroy();}
 @Override protected void onResume(){super.onResume();if(Prefs.get(this).getBoolean("enabled",false))launch(MonitorService.START);handler.post(refresh);}
 @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
}
